// === Tab: mySketch ===
// This is basicaly first sketch I do with my students after we go through p5js basics.
// It doesn't do anything special and still it has a power to impress students enough to 
// become a p5js or Processing followers.

// GLOBAL VARIABLES
let iterations = 2000; // number of iterations bubbles will be generated
let s = 100;
let b = 100;
let alpha = 0.42;
let h;

// SETUP
function setup() {
	createCanvas(windowWidth, windowHeight);
	background(100);
	colorMode(HSB);
	h = random(190, 210); // a color range - 190-210 => bluish color
}

// LOOP 
function draw() {

// [SENTINEL 專家 2 修復] 音訊座標數值防禦
if(typeof window.simulatedMouseX === 'number' && isNaN(window.simulatedMouseX)) window.simulatedMouseX = width*0.5;
if(typeof window.simulatedMouseY === 'number' && isNaN(window.simulatedMouseY)) window.simulatedMouseY = height*0.5;

	h = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, 360);
	s = map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, 0, 100);

	if(frameCount < iterations){
		let d = random(10, 50);
		noStroke();
		fill(h, s, b, alpha);
		ellipse(random(width), random(height), d, d);
	}
}

